const A=()=>api||window.YV_APP,B=()=>window.YV_BUILDER,P=()=>B().getPlan(),D=()=>A().data(),M=()=>A().maps();
const E=v=>A()?.esc(v)??String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=(key,lang=A()?.prefs().language||'zh')=>COPY[key]?.[Math.max(0,LANGS.indexOf(lang))]??key;
const T=text,TX=v=>A().tx(v),F=(type,x,key)=>A().field(type,x,key);
const projects=()=>D().projects.projects;
const nameInput=id=>{const x=D().categories.dataRequirements.find(v=>v.id===id);return x?TX(x.title):id;};
const btn=(action,label,extra='',cls='j17-button')=>`<button type="button" class="${cls}" data-j17="${action}" ${extra}>${label}</button>`;
const queryMatch=(x,q)=>!q||q.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean).every(w=>(x._search||JSON.stringify(x)).toLocaleLowerCase().includes(w));
const signature=()=>{const p=P();delete p.updated;return JSON.stringify([p,A().prefs().language,window.YV_EXPORT_LAYOUT?.options()]);};
const summary=()=>{const p=P();return {steps:p.stages.length,tools:p.tools.length,metrics:p.metrics.length,markers:p.markers.length,projects:p.projects.length};};
function readSettings(){try{const s=JSON.parse(localStorage.getItem('yv.journey.v17')||'{}');quality=s.quality==='high'?'high':'balanced';motion=s.motion!==false;wallOpacity=Number.isFinite(s.wallOpacity)?Math.min(.72,Math.max(.16,s.wallOpacity)):.42;}catch{}}
function saveSettings(){try{localStorage.setItem('yv.journey.v17',JSON.stringify({quality,motion,wallOpacity}));}catch{}}
function routeStage(){const s=new URLSearchParams(location.hash.split('?')[1]||'').get('stage');return STAGES.includes(s)?s:'scope';}
function go(next){if(!STAGES.includes(next))return;if(next===stage){feedback({kind:'stage',id:next,action:'navigate',label:T(next)});return;}pendingFocus=true;const hash='#journey?stage='+next,direction=STAGES.indexOf(next)<STAGES.indexOf(stage)?'backward':'forward';if(active&&window.YV_MODE_TRANSITIONS?.stage)return window.YV_MODE_TRANSITIONS.stage(hash,{direction});location.hash=hash;}
function reducedSceneMotion(){return !!window.YV_MODE_TRANSITIONS?.reduced();}
function syncMotionControl(){const el=document.querySelector('#journey [data-j17=motion]');if(!el)return;const reduced=reducedSceneMotion();el.disabled=reduced;el.setAttribute('aria-pressed',String(motion&&!reduced));el.title=T(reduced?'motionReduced':'motion');}
function state(){return {active,stage,selected:api?summary():null,generated:!!result,generating,quality,motion,wallOpacity,feedback:lastFeedback};}
function entryMarkup(){const current=A()?.route()==='workbench'?new URLSearchParams(location.hash.split('?')[1]||'').get('stage'):null,resume=STAGES.includes(current)?current:'scope';return `<a href="#journey?stage=${resume}" class="j17-entry"><span class="j17-entry-mark" aria-hidden="true">${A()?.icon('workflow')||'↗'}</span><span><strong>${E(T('entry'))}</strong><small>${E(T('entryHint'))}</small></span><span aria-hidden="true">↗</span></a>`;}
function counts(){const s=summary();return ['steps','tools','metrics','markers'].map(k=>`<span><b>${s[k]}</b> ${E(T(k))}</span>`).join('');}
function saveMarkup(){const s=B().recoveryState();return `<span class="j17-save" data-save-state="${E(s.status)}" aria-label="${E(T('status'))}"><i></i>${E(T(s.status==='saved'?'saved':'unsaved'))}</span>`;}
function gate(){return `<section id="journey" class="j17-shell j17-gate" data-active="false" data-stage="${stage}" aria-labelledby="j17-gate-title"><header class="j17-topbar"><a class="j17-brand" href="#overview" aria-label="YeastVar1011"><img src="assets/yeastvar-emblem.png" alt="" width="36" height="36"><span>YEASTVAR<span>1011</span><small>${E(T('planning'))}</small></span></a><div class="j17-top-actions"><span id="j17-save">${saveMarkup()}</span><select id="j17-language" aria-label="${E(T('language'))}">${LANGS.map((v,i)=>`<option value="${v}" ${api.prefs().language===v?'selected':''}>${['中文','English','Français','Español','Euskara'][i]}</option>`).join('')}</select><a href="#workbench?stage=${stage}" class="j17-exit" data-j17="exit">${E(T('standard'))} ↗</a></div></header><div class="j17-gate-main"><div class="j17-gate-heading"><span class="j17-eyebrow">YEASTVAR1011 / ${E(T('planning'))}</span><h1 id="j17-gate-title">${E(T('modeTitle'))}</h1><p>${E(T('modeIntro'))}</p></div><div class="j17-mode-grid"><article class="j17-mode-card is-default"><span class="j17-mode-label">${E(T('defaultMode'))}</span><div class="j17-mode-symbol" aria-hidden="true">${A().icon('workflow')}</div><h2>${E(T('classic'))}</h2><p>${E(T('classicHint'))}</p><a href="#workbench?stage=${stage}" class="j17-button j17-primary" data-j17="exit">${E(T('useClassic'))} →</a></article><article class="j17-mode-card is-immersive"><span class="j17-mode-label">${E(T('optionalMode'))}</span><div class="j17-mode-symbol" aria-hidden="true">${A().icon('markers')}</div><h2>${E(T('immersive'))}</h2><p>${E(T('immersiveHint'))}</p>${btn('start',E(T('start'))+' →','','j17-button j17-secondary')}</article></div><p class="j17-gate-note">${E(T('gateNote'))}</p><div class="j17-gate-summary"><div><span>${E(T('currentPlan'))}</span><strong>${E(P().title)}</strong></div><div class="j17-summary">${counts()}</div></div></div></section>`;}
function page(a){api=a||window.YV_APP;B().init(api);stage=routeStage();if(result&&result.signature!==signature())result=null;readSettings();if(!active)return gate();return `<section id="journey" class="j17-shell" data-active="true" data-stage="${stage}" data-generated="${stage==='review'&&!!result}" aria-label="${E(T('title'))}"><header class="j17-topbar"><a class="j17-brand" href="#overview" aria-label="YeastVar1011"><img src="assets/yeastvar-emblem.png" alt="" width="36" height="36"><span>YEASTVAR<span>1011</span><small>${E(T('title'))}</small></span></a><div class="j17-top-actions"><span id="j17-save">${saveMarkup()}</span><div class="j17-history">${btn('undo','↶',`aria-label="${E(T('undo'))}" title="${E(T('undo'))}" ${B().recoveryState().canUndo?'':'disabled'}`,'j17-icon-button')}${btn('redo','↷',`aria-label="${E(T('redo'))}" title="${E(T('redo'))}" ${B().recoveryState().canRedo?'':'disabled'}`,'j17-icon-button')}</div><select id="j17-language" aria-label="${E(T('language'))}">${LANGS.map((v,i)=>`<option value="${v}" ${api.prefs().language===v?'selected':''}>${['中文','English','Français','Español','Euskara'][i]}</option>`).join('')}</select>${btn('storage',A().icon('settings'),`aria-label="${E(T('storage'))}" title="${E(T('storage'))}"`,'j17-icon-button')}${btn('assistant',ASSISTANT_ICON,`aria-label="${E(T('assistant'))}" title="${E(T('assistant'))}"`,'j17-icon-button')}<a href="#workbench?stage=${stage}" class="j17-exit" data-j17="exit">${E(T('standard'))} ↗</a></div></header><div class="j17-layout"><nav class="j17-rail" aria-label="${E(T('title'))}">${STAGES.map((s,i)=>btn('go',`<span class="j17-step-index">${String(i+1).padStart(2,'0')}</span><span>${E(T(s))}</span>`,`data-stage="${s}" ${stage===s?'aria-current="step"':''}`,'j17-step'+(stage===s?' is-current':''))).join('')}</nav><section class="j17-stage" aria-label="${E(T('model'))}"><div class="j17-scene-wrap"><div id="j17-scenehost" aria-label="${E(T('model'))}" aria-busy="false"></div><div class="j17-scene-status" role="status" aria-live="polite" hidden><i aria-hidden="true"></i><span>${E(T('modelLoading'))}</span></div><div class="j17-scene-caption"><span class="j17-model-label">SACCHAROMYCES CEREVISIAE</span><h2>${E(T(stage))}</h2><p id="j17-scene-description">${E(T('modelHint'))}</p></div><div class="j17-scene-controls">${wallControl()}<select id="j17-quality" aria-label="${E(T('balanced'))}"><option value="balanced" ${quality==='balanced'?'selected':''}>${E(T('balanced'))}</option><option value="high" ${quality==='high'?'selected':''}>${E(T('high'))}</option></select>${btn('motion',api.icon('clock'),`aria-label="${E(T('motion'))}" title="${E(T(reducedSceneMotion()?'motionReduced':'motion'))}" aria-pressed="${motion&&!reducedSceneMotion()}" ${reducedSceneMotion()?'disabled':''}`,'j17-icon-button')}${btn('reset-view','↺',`aria-label="${E(T('resetView'))}" title="${E(T('resetView'))}"`,'j17-icon-button')}</div></div></section><aside class="j17-panel" aria-labelledby="j17-panel-title"><div class="j17-panel-header"><span class="j17-eyebrow">${String(STAGES.indexOf(stage)+1).padStart(2,'0')} / 06</span><h1 id="j17-panel-title" tabindex="-1">${E(T(stage))}</h1><p>${E(T(stage+'Q'))}</p></div><div id="j17-content" class="j17-content">${content()}</div></aside></div><footer class="j17-bottom"><div class="j17-summary" aria-live="polite">${counts()}</div><div class="j17-navigation">${btn('previous','← '+E(T('previous')),stage==='scope'?'disabled':'','j17-button j17-secondary')}${stage==='review'?result?btn('edit',E(T('edit')),'','j17-button j17-primary'):btn('generate',E(T('generate'))+' ↗','','j17-button j17-primary'):btn('next',E(T('next'))+' →','','j17-button j17-primary')}</div></footer><span class="j17-live sr-only" role="status" aria-live="polite"></span></section>`;}
function projectChoice(x,p=P()){return `<article class="j17-choice ${p.projects.includes(x.id)?'is-selected':''}"><label class="j17-choice-main"><input type="checkbox" data-j17-project="${E(x.id)}" ${p.projects.includes(x.id)?'checked':''}><span class="j17-card-copy"><strong>${E(F('projects',x,'title'))}</strong><small>${E(F('projects',x,'question')||F('projects',x,'goal'))}</small></span></label><div class="j17-choice-meta"><span>${E(T('needs'))}: ${(x.inputs||[]).map(nameInput).map(E).join(' · ')}</span><button type="button" class="j17-details" data-j17="details" data-type="project" data-id="${E(x.id)}">${E(T('details'))} ↗</button></div></article>`;}
function scopeContent(){const p=P(),ids=['mean_noise','noise_components','audit_raw','annotation_transfer'];return `<div class="j17-fields"><label>${E(T('planTitle'))}<input id="j17-plan-title" data-plan-field="title" value="${E(p.title)}" maxlength="200"></label><label>${E(T('objective'))}<textarea id="j17-objective" data-plan-field="objective" maxlength="5000" rows="2">${E(p.objective)}</textarea></label></div><section class="j17-section"><h2>${E(T('input'))}</h2><div class="j17-input-routes">${['raw_fastq','tagged_bam','count_matrix'].map(v=>`<label class="j17-route ${(window.YV_INPUTS.route(p))===v?'is-selected':''}"><input type="radio" name="j17-route" data-j17-route="${v}" value="${v}" ${window.YV_INPUTS.route(p)===v?'checked':''}><span>${E(T(v))}</span></label>`).join('')}</div><p class="j17-hint">${E(T('routeHint'))}</p><details class="j17-inventory" ${inventoryOpen?'open':''}><summary>${E(T('inventory'))}<span>${p.availableData.length}</span></summary><div class="j17-inventory-list">${D().categories.dataRequirements.map(x=>`<label title="${E(TX(x.description))}"><input id="j17-inventory-${x.id}" data-inventory="${x.id}" type="checkbox" ${p.availableData.includes(x.id)?'checked':''}><span>${E(nameInput(x.id))}</span></label>`).join('')}</div></details></section><section class="j17-section"><h2>${E(T('focus'))}</h2><div class="j17-list">${ids.map(id=>projects().find(x=>x.id===id)).filter(Boolean).map(x=>projectChoice(x,p)).join('')}</div><p class="j17-hint">${E(T('directionsHint'))}</p></section><p class="j17-hint j17-plan-note">${E(T('currentTemplate'))}</p>`;}
function visibleSteps(){const excluded=new Set(window.YV_INPUTS.excludedStages?.(P())||[]);return D().workflow.steps.filter(s=>(stage==='noise'?['noise','validation']:['design','fastq','tags','bam','matrix','cellcalling','ambient','doublets','cellqc','sampleqc','integration']).includes(s.id)&&!excluded.has(s.id));}
function searchBar(kind=''){const f=filters[stage];return `<div class="j17-filterbar"><label class="j17-search"><span class="sr-only">${E(T(kind==='projects'?'searchDirections':'search'))}</span><input type="search" id="j17-query" value="${E(f.query)}" placeholder="${E(T(kind==='projects'?'searchDirections':'search'))}" autocomplete="off"></label><label class="j17-only"><input id="j17-only-selected" type="checkbox" ${f.only?'checked':''}>${E(T('chosenOnly'))}</label></div>`;}
function paging(rows,make){const f=filters[stage];return `${rows.slice(0,f.limit).map(x=>make(x)).join('')||`<div class="j17-empty"><p>${E(T('empty'))}</p>${btn('clear',E(T('clear')))}</div>`}${rows.length>f.limit?btn('more',`${E(T('more'))} · ${Math.min(f.limit,rows.length)} / ${rows.length}`,'','j17-button j17-more'):''}`;}
function itemsForMethods(){const f=filters[stage],p=P();return (f.tab==='tools'?D().workflow.tools.filter(x=>x.steps.includes(f.step)):D().workflow.metrics.filter(x=>x.stepId===f.step)).filter(x=>(!f.only||p[f.tab].includes(x.id))&&queryMatch(x,f.query));}
function methodChoice(x){const f=filters[stage],tool=f.tab==='tools',type=tool?'tool':'metric',chosen=P()[f.tab].includes(x.id);return `<article class="j17-choice ${chosen?'is-selected':''}"><label class="j17-choice-main"><input type="checkbox" data-j17-${type}="${E(x.id)}" ${chosen?'checked':''}><span class="j17-card-copy"><strong>${E(tool?x.name:F('metrics',x,'name'))}</strong><small>${E(F(tool?'tools':'metrics',x,tool?'task':'definition'))}</small></span></label><div class="j17-choice-meta">${tool?`<span>${E(T('needs'))}: ${(x.applicability?.requiredData||[]).map(nameInput).map(E).join(' · ')}</span>`:'<span></span>'}<button type="button" class="j17-details" data-j17="details" data-type="${type}" data-id="${E(x.id)}">${E(T('details'))} ↗</button></div></article>`;}
function methodsContent(){const f=filters[stage],steps=visibleSteps();if(!steps.some(s=>s.id===f.step))f.step=steps[0]?.id||'';return `<label class="j17-select-label">${E(T('step'))}<select id="j17-step">${steps.map(s=>`<option value="${s.id}" ${f.step===s.id?'selected':''}>${E(F('steps',s,'title'))}</option>`).join('')}</select></label><div class="j17-tabs" role="group" aria-label="${E(T('tools'))} / ${E(T('metrics'))}">${['metrics','tools'].map(k=>btn('tab',E(T(k)),`data-tab="${k}" aria-pressed="${f.tab===k}"`,f.tab===k?'is-active':'')).join('')}</div>${searchBar()}<div id="j17-results" class="j17-list">${paging(itemsForMethods(),methodChoice)}</div>`;}
function markerRows(){const f=filters.annotation,chosen=new Set(P().markers.map(x=>x.id));return D().markers.markers.filter(m=>(!f.only||chosen.has(m.id))&&(!f.phase||(m.phases||[]).includes(f.phase))&&(!f.tag||(m.tags||[]).includes(f.tag))&&queryMatch(m,f.query)).sort((a,b)=>Number(chosen.has(b.id))-Number(chosen.has(a.id))||Number(!!b.seed)-Number(!!a.seed)||a.symbol.localeCompare(b.symbol));}
function markerChoice(m){const chosen=P().markers.some(v=>v.id===m.id),tags=[...(m.phases||[]),...(m.tags||[]).slice(0,2)].map(TX);return `<article class="j17-choice ${chosen?'is-selected':''}"><label class="j17-choice-main"><input type="checkbox" data-j17-marker="${E(m.id)}" ${chosen?'checked':''}><span class="j17-card-copy"><strong>${E(m.symbol)} <em>${E(m.systematic)}</em></strong><small>${E(tags.join(' · '))}</small></span></label><div class="j17-choice-meta"><span>${E((m.uses||[]).slice(0,1).map(TX).join(''))}</span><button type="button" class="j17-details" data-j17="details" data-type="marker" data-id="${E(m.id)}">${E(T('evidence'))} ↗</button></div></article>`;}
function annotationContent(){const f=filters.annotation,tags=[...new Set(D().markers.markers.flatMap(m=>m.tags||[]))].sort((a,b)=>TX(a).localeCompare(TX(b)));return `${searchBar()}<div class="j17-filter-pair"><label>${E(T('phase'))}<select id="j17-phase"><option value="">${E(T('all'))}</option>${['G1','G1/S','S','G2','G2/M','M','M/G1'].map(v=>`<option value="${v}" ${f.phase===v?'selected':''}>${v}</option>`).join('')}</select></label><label>${E(T('tag'))}<select id="j17-tag"><option value="">${E(T('all'))}</option>${tags.map(v=>`<option value="${E(v)}" ${f.tag===v?'selected':''}>${E(TX(v))}</option>`).join('')}</select></label></div><p class="j17-hint">${E(T('assignmentHint'))}</p><a href="#markers" class="j17-library-link">${E(T('fullMarkers'))} ↗</a><div id="j17-results" class="j17-list">${paging(markerRows(),markerChoice)}</div>`;}
function extensionRows(){const f=filters.extensions,p=P();return projects().filter(x=>(!f.category||x.categoryId===f.category)&&(!f.only||p.projects.includes(x.id))&&queryMatch(x,f.query));}
function extensionsContent(){const f=filters.extensions,ids=new Set(projects().map(p=>p.categoryId));return `${searchBar('projects')}<label class="j17-select-label">${E(T('focus'))}<select id="j17-category"><option value="">${E(T('all'))}</option>${D().categories.categories.filter(x=>ids.has(x.id)).map(x=>`<option value="${x.id}" ${f.category===x.id?'selected':''}>${E(TX(x.title))}</option>`).join('')}</select></label><div id="j17-results" class="j17-list">${paging(extensionRows(),projectChoice)}</div>`;}
function inputStatus(x){return {declared:'available','planned-output':'planned','conditional-output':'conditional'}[x.status]||'pending';}
function reviewContent(){if(result)return resultContent();const p=P(),r=B().inputReview(),s=summary();return `<div class="j17-count-grid">${['steps','tools','metrics','markers'].map(k=>`<div><strong>${s[k]}</strong><span>${E(T(k))}</span></div>`).join('')}</div><details class="j17-review-inputs" open><summary>${E(T('inputReview'))}<span>${r.inputs.length}</span></summary><div class="j17-review-list">${r.inputs.map(x=>`<div><span>${E(nameInput(x.id))}</span><small data-status="${E(x.status)}">${E(T(inputStatus(x)))}</small></div>`).join('')||`<p>${E(T('noInputs'))}</p>`}</div></details><section class="j17-section"><h2>${E(T('outputs'))}</h2><p class="j17-hint">${E(T('outputsHint'))}</p><div class="j17-list">${(D().projects.resultSpecifications||[]).map(s=>`<article class="j17-choice ${(p.resultSpecificationIds||[]).includes(s.id)?'is-selected':''}"><label class="j17-choice-main"><input type="checkbox" data-j17-result="${s.id}" ${(p.resultSpecificationIds||[]).includes(s.id)?'checked':''}><span class="j17-card-copy"><strong>${E(TX(s.title))}</strong><small>${E(TX(s.description))}</small></span></label></article>`).join('')}</div></section>${error?`<p class="j17-error" role="alert">${E(T('failure'))}</p>`:''}`;}
function resultContent(){return `<section class="j17-result"><div class="j17-result-heading"><span class="j17-result-check" aria-hidden="true">${A().icon('check')}</span><h2>${E(T('generated'))}</h2><p>${E(T('generatedHint'))}</p></div><div class="j17-result-actions">${btn('download-html',E(T('document')),'','j17-button j17-primary')}${btn('download-json',E(T('backup')))}</div><iframe class="j17-preview" title="${E(T('preview'))}" sandbox="allow-popups allow-popups-to-escape-sandbox" referrerpolicy="no-referrer"></iframe><a href="#workbench?stage=review" class="j17-library-link">${E(T('exportFull'))} ↗</a></section>`;}
function content(){return stage==='scope'?scopeContent():stage==='prep'||stage==='noise'?methodsContent():stage==='annotation'?annotationContent():stage==='extensions'?extensionsContent():reviewContent();}
function mountResult(){const frame=document.querySelector('.j17-preview');if(frame&&result)frame.srcdoc=result.preview;}
function refreshContent(focus){const host=document.querySelector('#j17-content');if(!host)return;const scroll=host.scrollTop;host.innerHTML=content();host.scrollTop=scroll;mountResult();if(focus)host.querySelector(focus)?.focus({preventScroll:true});}
function refreshResults(){const el=document.querySelector('#j17-results');if(!el)return;el.innerHTML=stage==='annotation'?paging(markerRows(),markerChoice):stage==='extensions'?paging(extensionRows(),projectChoice):paging(itemsForMethods(),methodChoice);}
function refreshStatus(){const root=document.querySelector('#journey');if(!root)return;const s=B().recoveryState(),saved=root.querySelector('#j17-save');if(saved)saved.innerHTML=saveMarkup();root.querySelector('[data-j17=undo]')?.toggleAttribute('disabled',!s.canUndo);root.querySelector('[data-j17=redo]')?.toggleAttribute('disabled',!s.canRedo);const c=root.querySelector('.j17-summary');if(c)c.innerHTML=counts();}
function recordFor(kind,id){return(kind==='marker'?D().markers.markers:kind==='metric'?D().workflow.metrics:kind==='tool'?D().workflow.tools:kind==='project'?projects():[]).find(x=>x.id===id);}
function semanticFor(record,id){
 const s=JSON.stringify([id,record?.tags,record?.uses,record?.title,record?.name,record?.function,record?.symbol]).toLowerCase();
 if(/mitochond|线粒体|respirat/.test(s))return 'network';
 if(/vacuol|液泡/.test(s))return 'vacuole';
 if(/cell.wall|细胞壁|cellwall|chitin/.test(s))return 'wall';
 if(/budd|cytokines|芽|胞质分裂/.test(s))return 'bud';
 if(/nucle|intron|exon|splic|chromatin|内含|外显|剪接|染色质|转录/.test(s))return 'nucleus';
 if(/network|endoplasmic|膜|grn|regulat|调控|网络/.test(s))return 'network';
 return 'whole';
}
function feedback({kind='choice',id='',action='select',selected,record,label='',el,semantic}={}){
 if(!active)return;
 const rec=record||recordFor(kind,id),name=String(label||rec?.symbol||el?.closest('.j17-choice')?.querySelector('strong')?.textContent||id).trim().slice(0,100);
 const verb=T(action==='deselect'?'deselected':action==='inspect'?'inspecting':action==='filter'?'filtered':action==='select'?'selected':'selectedAdded');
 lastFeedback={kind,id,action,selected,label:name,semantic:semantic||semanticFor(rec,id)};
 window.YV_JOURNEY_SCENE?.react({...lastFeedback,stage,tags:rec?.tags||[],counts:summary()});
 const wrap=document.querySelector('.j17-scene-wrap');if(!wrap)return;
 let notice=wrap.querySelector('.j19-feedback');if(!notice){notice=document.createElement('div');notice.className='j19-feedback';notice.setAttribute('aria-hidden','true');wrap.append(notice);}
 notice.dataset.kind=kind;notice.dataset.action=action;notice.innerHTML=`<span class="j19-feedback-symbol">${A().icon(action==='deselect'?'close':action==='inspect'?'search':'check')}</span><span><small>${E(verb)}</small><strong>${E(name||T(stage))}</strong></span>`;
 notice.hidden=false;notice.getAnimations().forEach(a=>a.cancel());
 if(!reducedSceneMotion())notice.animate([{opacity:0,transform:'translate3d(0,12px,0) scale(.97)'},{opacity:1,transform:'none'}],{duration:340,easing:'cubic-bezier(.16,1,.3,1)'});
 clearTimeout(feedbackTimer);feedbackTimer=setTimeout(()=>{notice.hidden=true;},3600);
 const live=document.querySelector('.j17-live');if(live)live.textContent=verb+(name?' · '+name:'');
 const card=el?.closest('.j17-choice,.j17-route');if(card&&!reducedSceneMotion())card.animate([{boxShadow:'inset 0 0 0 1px #c4ede8aa',backgroundColor:'#82cdc828'},{boxShadow:'inset 0 0 0 1px #c4ede800',backgroundColor:'transparent'}],{duration:650,easing:'ease-out'});
}
function changed(el){result=null;error=false;document.querySelector('#journey')?.setAttribute('data-generated','false');refreshStatus();el?.closest('.j17-choice')?.classList.toggle('is-selected',el.checked);document.querySelectorAll('.j17-route').forEach(x=>x.classList.toggle('is-selected',!!x.querySelector('input')?.checked));const ds=el?.dataset||{},kind=ds.j17Marker?'marker':ds.j17Metric?'metric':ds.j17Tool?'tool':ds.j17Project?'project':ds.inventory?'input':ds.j17Route?'input':'choice',id=ds.j17Marker||ds.j17Metric||ds.j17Tool||ds.j17Project||ds.j17Route||ds.j17Result||ds.inventory||ds.planField||'';feedback({kind,id,action:el?.type==='checkbox'&&!el.checked?'deselect':'select',selected:el?.checked,el,label:ds.j17Route?T(ds.j17Route):ds.inventory?nameInput(ds.inventory):el?.closest('label')?.querySelector('strong')?.textContent});if(el&&!el.checked&&filters[stage]?.only){refreshResults();(document.querySelector('#j17-results input[type=checkbox]')||document.querySelector('#j17-query'))?.focus({preventScroll:true});}}
